import { Injectable, Module } from "@nestjs/common"
import { NestFactory } from "@nestjs/core"
import * as bcrypt from "bcryptjs"

abstract class HashingService {
    abstract hash(data: string): Promise<string>
    abstract compare(data: string, encrypted: string): Promise<boolean>
}

@Injectable()
class BcryptService implements HashingService {
    hash(data: string) { return bcrypt.hash(data, 10) }
    compare(data: string, encrypted: string) { return bcrypt.compare(data, encrypted) }
}

@Injectable()
class UsersService {
    constructor(private readonly hashing: HashingService) {} // bcrypt haqida hech narsa bilmaydi
    async register(password: string) { return { passwordHash: await this.hashing.hash(password) } }
}

@Module({ providers: [{ provide: HashingService, useClass: BcryptService }, UsersService] })
class AppModule {}

async function main() {
    const app = await NestFactory.createApplicationContext(AppModule, { logger: false })
    const { passwordHash } = await app.get(UsersService).register("parol")
    console.log("bcrypt xesh:", passwordHash.startsWith("$2"))
    console.log("injekt qilingan klass:", app.get(HashingService).constructor.name)
    await app.close()
}
main()

import { Body, Controller, Injectable, Module, Post } from "@nestjs/common"
