function score(p: string) {
    let s = 0
    if (p.length >= 8) s++
    if (p.length >= 12) s++
    if (/[a-z]/.test(p) && /[A-Z]/.test(p)) s++
    if (/\d/.test(p)) s++
    if (/[^A-Za-z0-9]/.test(p)) s++
    return ["juda zaif", "zaif", "o'rtacha", "yaxshi", "kuchli", "juda kuchli"][s]
}
