import { randomBytes, scrypt, timingSafeEqual } from "node:crypto"
import { promisify } from "node:util"

const scryptAsync = promisify(scrypt) as (p: string, s: Buffer, len: number) => Promise<Buffer>
async function hash(p: string) { const salt = randomBytes(16); const key = await scryptAsync(p, salt, 32); return `scrypt$${salt.toString("hex")}$${key.toString("hex")}` }
async function verify(p: string, stored: string) {
    const [, saltHex, keyHex] = stored.split("$")
    const key = await scryptAsync(p, Buffer.from(saltHex, "hex"), 32)
    return timingSafeEqual(key, Buffer.from(keyHex, "hex"))
}

async function main() {
    const stored = await hash("Salom123")
    console.log("Format:", stored.split("$")[0], "| qismlar:", stored.split("$").length)
    console.log("to'g'ri parol:", await verify("Salom123", stored), "| noto'g'ri:", await verify("salom123", stored))
}
