import { createCipheriv, createDecipheriv, randomBytes } from "node:crypto"

const key = Buffer.alloc(32, 7)
function encrypt(text: string) {
    const iv = randomBytes(12)
    const c = createCipheriv("aes-256-gcm", key, iv)
    const data = Buffer.concat([c.update(text, "utf8"), c.final()])
    return [iv, c.getAuthTag(), data].map(b => b.toString("base64")).join(".")
}
function decrypt(payload: string) {
    const [iv, tag, data] = payload.split(".").map(s => Buffer.from(s, "base64"))
    const d = createDecipheriv("aes-256-gcm", key, iv)
    d.setAuthTag(tag)
    return Buffer.concat([d.update(data), d.final()]).toString("utf8")
}
const enc = encrypt("+998901234567")
console.log("Shifrlangan qismlar:", enc.split(".").length, "| ochiq matn ko'rinadimi:", enc.includes("998"))
console.log("Ochilgan:", decrypt(enc))
try { decrypt(enc.slice(0, -2) + "AA") } catch (e) { console.log("Buzilgan ma'lumot:", (e as Error).message) }

import { createHash } from "node:crypto"

const sha1 = (s: string) => createHash("sha1").update(s).digest("hex").toUpperCase()
const leakedDb = new Set(["password", "123456", "qwerty"].map(sha1))
function fakeRangeApi(prefix: string) { return [...leakedDb].filter(h => h.startsWith(prefix)).map(h => h.slice(5)) }
function isPwned(password: string) {
