import bcrypt from "bcryptjs"
import { createHmac } from "node:crypto"

const PEPPERS: Record<string, string> = { v1: "eski-pepper", v2: "yangi-pepper" }
const CURRENT = "v2"
const peppered = (p: string, v: string) => createHmac("sha256", PEPPERS[v]).update(p).digest("base64")
async function hash(p: string, v = CURRENT) { return `${v}:${await bcrypt.hash(peppered(p, v), 4)}` }
async function verify(p: string, stored: string) {
    const [v, h] = [stored.slice(0, stored.indexOf(":")), stored.slice(stored.indexOf(":") + 1)]
    return { ok: await bcrypt.compare(peppered(p, v), h), needsRehash: v !== CURRENT }
}

