import { Injectable, UnauthorizedException, BadRequestException } from '@nestjs/common';
import { JwtService } from '@nestjs/jwt';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import * as bcrypt from 'bcrypt';
import { User } from '../users/entities/user.entity';
import { RegisterDto, LoginDto } from './dto/auth.dto';

@Injectable()
export class AuthService {
  constructor(
    @InjectRepository(User) private userRepo: Repository<User>,
    private jwtService: JwtService // Token yaratib beruvchi xizmat
  ) {}

  // [REGISTER] - Yangi foydalanuvchini ro'yxatdan o'tkazish
  async register(dto: RegisterDto) {
    // 1. Email band emasligini tekshiramiz
    const existingUser = await this.userRepo.findOne({ where: { email: dto.email } });
    if (existingUser) {
      throw new BadRequestException('Bu email allaqachon band!');
    }

    // 2. Parolni Bcrypt yordamida xashlaymiz (10 - salt rounds)
    const hashedPassword = await bcrypt.hash(dto.password, 10);

    // 3. Bazaga yozamiz
    const newUser = this.userRepo.create({
      email: dto.email,
      password: hashedPassword,
    });
    await this.userRepo.save(newUser);

    return { message: "Muvaffaqiyatli ro'yxatdan o'tdingiz!" };
  }

  // [LOGIN] - Tizimga kirish va Token qaytarish
  async login(dto: LoginDto) {
    // 1. Foydalanuvchini bazadan izlaymiz
    const user = await this.userRepo.findOne({ where: { email: dto.email } });
    if (!user) throw new UnauthorizedException('Email yoki parol xato');

    // 2. Parolni Bcrypt yordamida tekshiramiz
    const isPasswordMatch = await bcrypt.compare(dto.password, user.password);
    if (!isPasswordMatch) throw new UnauthorizedException('Email yoki parol xato');

    // 3. JWT Token yaratamiz (Payload ga kerakli user infolarni tiqamiz)
    const payload = { sub: user.id, email: user.email };
    const token = this.jwtService.sign(payload);

    // 4. Client ga tokenni qaytaramiz
    return {
      message: "Tizimga kirdingiz",
      access_token: token,
    };
  }
}

import { Body, ConflictException, Controller, Injectable, Module, Post, UnauthorizedException } from "@nestjs/common"
import { JwtModule, JwtService } from "@nestjs/jwt"
import * as bcrypt from "bcryptjs"

type User = { id: number; email: string; passwordHash: string }

@Injectable()
class AuthService {
    private users: User[] = []
    constructor(private readonly jwt: JwtService) {}

    async register(email: string, password: string) {
        if (this.users.some(u => u.email === email)) throw new ConflictException("Email band")
        const user = { id: this.users.length + 1, email, passwordHash: await bcrypt.hash(password, 10) }
        this.users.push(user)
        return { id: user.id, email }
    }

    async login(email: string, password: string) {
        const user = this.users.find(u => u.email === email)
        if (!user || !(await bcrypt.compare(password, user.passwordHash))) {
            throw new UnauthorizedException("Email yoki parol noto'g'ri")
        }
        const token = await this.jwt.signAsync({ sub: user.id, email })
        return { tokenType: "Bearer", tokenLength: token.length > 100 }
    }
}

