import { Body, Controller, Injectable, Module, Post, UnauthorizedException } from "@nestjs/common"
import { JwtModule, JwtService } from "@nestjs/jwt"

@Injectable()
class TokenService {
    constructor(private readonly jwt: JwtService) {}
    async pair(userId: number) {
        return {
            accessToken: await this.jwt.signAsync({ sub: userId, type: "access" }, { secret: "ACCESS", expiresIn: "15m" }),
            refreshToken: await this.jwt.signAsync({ sub: userId, type: "refresh" }, { secret: "REFRESH", expiresIn: "7d" }),
        }
    }
    async refresh(token: string) {
        const p = await this.jwt.verifyAsync(token, { secret: "REFRESH" }).catch(() => null)
        if (p?.type !== "refresh") throw new UnauthorizedException("Refresh token yaroqsiz")
        return this.pair(p.sub)
    }
}

