@Injectable()
class RefreshStore {
    private active = new Map<string, number>() // token → userId
    issue(userId: number) { const t = randomUUID(); this.active.set(t, userId); return t }
    rotate(token: string) {
        const userId = this.active.get(token)
        if (userId === undefined) throw new UnauthorizedException("Token allaqachon ishlatilgan yoki yo'q")
        this.active.delete(token)
        return this.issue(userId)
    }
}

