import { CanActivate, Controller, ExecutionContext, Get, Injectable, Module, Post, Req, UnauthorizedException, UseGuards } from "@nestjs/common"
import { JwtModule, JwtService } from "@nestjs/jwt"

@Injectable() class Denylist { jtis = new Set<string>() }

@Injectable()
class JwtGuard implements CanActivate {
    constructor(private readonly jwt: JwtService, private readonly deny: Denylist) {}
    async canActivate(ctx: ExecutionContext) {
        const req = ctx.switchToHttp().getRequest()
        const payload = await this.jwt.verifyAsync(req.headers.authorization?.slice(7) ?? "").catch(() => null)
        if (!payload || this.deny.jtis.has(payload.jti)) throw new UnauthorizedException()
        req.user = payload
        return true
    }
}

@Controller()
@UseGuards(JwtGuard)
class AppController {
    constructor(private readonly deny: Denylist) {}
    @Get("me") me(@Req() r: any) { return { sub: r.user.sub } }
    @Post("logout") logout(@Req() r: any) { this.deny.jtis.add(r.user.jti); return { loggedOut: true } }
}

