import { randomBytes } from "node:crypto"

@Injectable()
class ResetService {
    user = { email: "ali@mail.uz", passwordHash: bcrypt.hashSync("eski", 8) }
    private tokens = new Map<string, number>() // token → amal qilish muddati
    request(email: string) {
        if (email !== this.user.email) return { sent: true } // email mavjudligini oshkor qilmaymiz
        const t = randomBytes(20).toString("hex")
        this.tokens.set(t, Date.now() + 15 * 60_000)
        return { sent: true, _devToken: t }
    }
    async reset(token: string, password: string) {
        const exp = this.tokens.get(token)
        if (!exp || exp < Date.now()) throw new BadRequestException("Token yaroqsiz yoki muddati o'tgan")
        this.tokens.delete(token)
        this.user.passwordHash = await bcrypt.hash(password, 10)
        return { reset: true }
    }
}

