import { BadRequestException, Injectable } from "@nestjs/common"
import { createHash, randomInt } from "node:crypto"

@Injectable()
class OtpService {
    private codes = new Map<string, { hash: string; expires: number; attempts: number }>()
    now = () => Date.now()
    private sha = (s: string) => createHash("sha256").update(s).digest("hex")
    send(phone: string) {
        const code = String(randomInt(100000, 1000000))
        this.codes.set(phone, { hash: this.sha(code), expires: this.now() + 2 * 60_000, attempts: 0 })
        return code   // haqiqiyda — SMS
    }
    verify(phone: string, code: string) {
        const e = this.codes.get(phone)
        if (!e || e.expires < this.now()) throw new BadRequestException("Kod topilmadi yoki muddati o'tgan")
        if (++e.attempts > 3) throw new BadRequestException("Urinishlar tugadi")
        if (e.hash !== this.sha(code)) return false
        this.codes.delete(phone)
        return true
    }
}

