import { Injectable, UnauthorizedException } from "@nestjs/common"
import { JwtService } from "@nestjs/jwt"

@Injectable()
class TwoFactorAuth {
    constructor(private readonly jwt: JwtService, private readonly codes = new Map<number, string>([[1, "482913"]])) {}
    async loginStep1(userId: number, has2fa: boolean) {
        if (!has2fa) return { accessToken: await this.jwt.signAsync({ sub: userId }) }
        return { requires2fa: true, tempToken: await this.jwt.signAsync({ sub: userId, stage: "2fa" }, { expiresIn: "5m" }) }
    }
    async loginStep2(tempToken: string, code: string) {
        const p = await this.jwt.verifyAsync(tempToken)
        if (p.stage !== "2fa" || this.codes.get(p.sub) !== code) throw new UnauthorizedException("Kod noto'g'ri")
        return { accessToken: await this.jwt.signAsync({ sub: p.sub }) }
    }
}

async function main() {
    const s = new TwoFactorAuth(new JwtService({ secret: "maxfiy" }))
    const step1 = await s.loginStep1(1, true)
    console.log("1-bosqich:", { requires2fa: step1.requires2fa, tempToken: step1.tempToken ? "<jwt>" : null })
    try { await s.loginStep2(step1.tempToken!, "000000") } catch (e) { console.log("noto'g'ri kod:", (e as Error).message) }
    const step2 = await s.loginStep2(step1.tempToken!, "482913")
    console.log("2-bosqich: access token olindi:", !!step2.accessToken)
}
