import { createHmac } from "node:crypto"

function totp(secret: Buffer, unixTime: number, digits = 6, step = 30) {
    const counter = Buffer.alloc(8)
    counter.writeBigUInt64BE(BigInt(Math.floor(unixTime / step)))
    const h = createHmac("sha1", secret).update(counter).digest()
    const offset = h[h.length - 1] & 0xf
    const code = (h.readUInt32BE(offset) & 0x7fffffff) % 10 ** digits
    return String(code).padStart(digits, "0")
}
const secret = Buffer.from("12345678901234567890")
console.log("RFC test (t=59, 8 raqam):", totp(secret, 59, 8), "← kutilgan 94287082")
console.log("6 raqamli kod t=1111111109:", totp(secret, 1111111109))
console.log("30 s ichida kod o'zgarmaydi:", totp(secret, 1111111110) === totp(secret, 1111111119))

