const failures = new Map<string, number>()
const delayFor = (n: number) => (n <= 2 ? 0 : Math.min(2 ** (n - 2), 60))
function attempt(user: string, ok: boolean) {
    if (ok) { failures.delete(user); return "kirdi" }
    const n = (failures.get(user) ?? 0) + 1
    failures.set(user, n)
    return `xato #${n} → keyingi urinishgacha ${delayFor(n)} s kuting`
}
