import { Controller, HttpCode, Injectable, Module, Post, Req, UnauthorizedException, UseGuards } from "@nestjs/common"
import { AuthGuard, PassportModule, PassportStrategy } from "@nestjs/passport"
import { Strategy } from "passport-local"
import * as bcrypt from "bcryptjs"

const users = [{ id: 1, email: "ali@mail.uz", passwordHash: bcrypt.hashSync("12345678", 8) }]

@Injectable()
class LocalStrategy extends PassportStrategy(Strategy) {
    constructor() { super({ usernameField: "email" }) }
    async validate(email: string, password: string) {
        const user = users.find(u => u.email === email)
        if (!user || !(await bcrypt.compare(password, user.passwordHash))) throw new UnauthorizedException("Login yoki parol xato")
        return { id: user.id, email: user.email }
    }
}

