import { Controller, Get, Injectable, Module, Req, UseGuards } from "@nestjs/common"
import { AuthGuard, PassportModule, PassportStrategy } from "@nestjs/passport"
import type { Request } from "express"
import { createHmac } from "node:crypto"
import { Strategy } from "passport-strategy"

const CLIENTS: Record<string, string> = { "shop-7": "shop-secret" }
class HmacStrategy extends Strategy {
    authenticate(req: Request) {
        const client = String(req.headers["x-client-id"] ?? ""), sig = String(req.headers["x-signature"] ?? "")
        const secret = CLIENTS[client]
        if (!secret) return this.fail({ message: "mijoz noma'lum" }, 401)
        const expected = createHmac("sha256", secret).update(`${req.method} ${req.url}`).digest("hex")
        return sig === expected ? this.success({ client }) : this.fail({ message: "imzo noto'g'ri" }, 401)
    }
}
@Injectable() class HmacAuth extends PassportStrategy(HmacStrategy, "hmac") { validate(u: object) { return u } }
@Controller("partner") class P { @Get("balance") @UseGuards(AuthGuard("hmac")) b(@Req() req: { user: object }) { return { ...req.user, balance: 1_200_000 } } }
@Module({ imports: [PassportModule], controllers: [P], providers: [HmacAuth] }) class AppModule {}

async function main() {
    const http = await testApp(AppModule)
    const sig = createHmac("sha256", "shop-secret").update("GET /partner/balance").digest("hex")
    await http.get("/partner/balance", { "X-Client-Id": "shop-7", "X-Signature": sig })
    await http.get("/partner/balance", { "X-Client-Id": "shop-7", "X-Signature": "soxta" })
    await http.close()
}
main()

