import { ExtractJwt, Strategy } from "passport-jwt"

const SECRET = "s3cret"
@Injectable() class JwtStrategy extends PassportStrategy(Strategy) {
    constructor() { super({ jwtFromRequest: ExtractJwt.fromAuthHeaderAsBearerToken(), secretOrKey: SECRET, passReqToCallback: true }) }
    validate(req: Request, p: { sub: number; tenant: string }) {
        if (req.headers["x-tenant"] !== p.tenant) throw new ForbiddenException(`Token ${p.tenant} uchun, so'rov ${req.headers["x-tenant"]} uchun`)
        return { id: p.sub, tenant: p.tenant }
    }
}
@Controller("orders") class O { @Get() @UseGuards(AuthGuard("jwt")) o() { return ["#1"] } }
@Module({ imports: [PassportModule.register({ defaultStrategy: "jwt" })], controllers: [O], providers: [JwtStrategy] }) class AppModule {}

async function main() {
    const http = await testApp(AppModule)
    const token = new JwtService({ secret: SECRET }).sign({ sub: 1, tenant: "acme" })
    await http.get("/orders", { Authorization: `Bearer ${token}`, "X-Tenant": "acme" })
    await http.get("/orders", { Authorization: `Bearer ${token}`, "X-Tenant": "globex" })
    await http.close()
}
main()

