import { CanActivate, Controller, ExecutionContext, ForbiddenException, Get, Injectable, Module, Post, SetMetadata, UseGuards } from "@nestjs/common"
import { Reflector } from "@nestjs/core"
import { JwtService } from "@nestjs/jwt"
import { AuthGuard, PassportModule, PassportStrategy } from "@nestjs/passport"
import { ExtractJwt, Strategy } from "passport-jwt"

const SECRET = "s3cret"
@Injectable() class JwtStrategy extends PassportStrategy(Strategy) {
    constructor() { super({ jwtFromRequest: ExtractJwt.fromAuthHeaderAsBearerToken(), secretOrKey: SECRET }) }
    validate(p: { sub: string; scope: string }) { return { client: p.sub, scopes: p.scope.split(" ") } }
}
const Scopes = (...s: string[]) => SetMetadata("scopes", s)
@Injectable() class ScopesGuard implements CanActivate {
    constructor(private r: Reflector) {}
    canActivate(ctx: ExecutionContext) {
        const need = this.r.get<string[]>("scopes", ctx.getHandler()) ?? []
        const have: string[] = ctx.switchToHttp().getRequest().user.scopes
        const missing = need.filter(s => !have.includes(s))
        if (missing.length) throw new ForbiddenException(`Yetishmayotgan scope: ${missing.join(", ")}`)
        return true
    }
}
@Controller("orders") @UseGuards(AuthGuard("jwt"), ScopesGuard) class O {
    @Get() @Scopes("orders:read") list() { return [] }
    @Post() @Scopes("orders:write") create() { return { id: 1 } }
}
@Module({ imports: [PassportModule.register({ defaultStrategy: "jwt" })], controllers: [O], providers: [JwtStrategy] }) class AppModule {}

async function main() {
    const http = await testApp(AppModule)
    const auth = { Authorization: `Bearer ${new JwtService({ secret: SECRET }).sign({ sub: "crm", scope: "orders:read" })}` }
    await http.get("/orders", auth)
    await http.post("/orders", {}, auth)
    await http.close()
}
main()

