import { Controller, Get, Injectable, Module, Req, UseGuards } from "@nestjs/common"
import { JwtService } from "@nestjs/jwt"
import { AuthGuard, PassportModule, PassportStrategy } from "@nestjs/passport"
import { ExtractJwt, Strategy } from "passport-jwt"

const ISSUERS: Record<string, string> = { "auth.recipe.uz": "main-secret", "partner.uz": "partner-secret" }
@Injectable() class JwtStrategy extends PassportStrategy(Strategy) {
    constructor() {
        super({
            jwtFromRequest: ExtractJwt.fromAuthHeaderAsBearerToken(),
            secretOrKeyProvider: (_r: unknown, raw: string, done: (e: Error | null, k?: string) => void) => {
                const iss = JSON.parse(Buffer.from(raw.split(".")[1], "base64url").toString()).iss
                ISSUERS[iss] ? done(null, ISSUERS[iss]) : done(new Error("ishonchsiz issuer"))
            },
        })
    }
    validate(p: { sub: string; iss: string }) { return { id: p.sub, from: p.iss } }
}
@Controller("me") class M { @Get() @UseGuards(AuthGuard("jwt")) me(@Req() req: { user: object }) { return req.user } }
@Module({ imports: [PassportModule.register({ defaultStrategy: "jwt" })], controllers: [M], providers: [JwtStrategy] }) class AppModule {}

async function main() {
    const http = await testApp(AppModule)
    const tok = (iss: string, secret: string) => new JwtService({ secret }).sign({ sub: "u1" }, { issuer: iss })
    await http.get("/me", { Authorization: `Bearer ${tok("auth.recipe.uz", "main-secret")}` })
    await http.get("/me", { Authorization: `Bearer ${tok("partner.uz", "partner-secret")}` })
    await http.get("/me", { Authorization: `Bearer ${tok("evil.com", "x")}` })
    await http.close()
}
