import { Body, Controller, HttpCode, Injectable, Module, Post, Req, UnauthorizedException, UseGuards } from "@nestjs/common"
import { AuthGuard, PassportModule, PassportStrategy } from "@nestjs/passport"
import { Strategy } from "passport-local"

const users = [{ email: "ali@mail.uz", password: "Salom123", name: "Ali" }]
@Injectable() class LocalStrategy extends PassportStrategy(Strategy) {
    constructor() { super({ usernameField: "email" }) }
    validate(email: string, password: string) {
        const u = users.find(x => x.email === email && x.password === password)
