import { CanActivate, ExecutionContext, Controller, Get, Injectable, Module, UnauthorizedException, UseGuards } from "@nestjs/common"
import { JwtModule, JwtService } from "@nestjs/jwt"

const SECRET = "s3cret"
@Injectable() class JwtGuard implements CanActivate {
    constructor(private jwt: JwtService) {}
    async canActivate(ctx: ExecutionContext) {
        const req = ctx.switchToHttp().getRequest()
        const token = String(req.headers.authorization ?? "").replace(/^Bearer /, "")
        try { req.user = await this.jwt.verifyAsync(token); return true }
        catch (e) {
            const name = (e as Error).name
            throw new UnauthorizedException({ TokenExpiredError: "TOKEN_EXPIRED — refresh qiling", JsonWebTokenError: "TOKEN_INVALID — qayta kiring" }[name] ?? "TOKEN_MISSING")
        }
    }
}
@Controller("me") class M { @Get() @UseGuards(JwtGuard) me() { return "ok" } }
@Module({ imports: [JwtModule.register({ secret: SECRET })], controllers: [M] }) class AppModule {}

async function main() {
    const http = await testApp(AppModule)
    const jwt = new JwtService({ secret: SECRET })
    await http.get("/me", { Authorization: `Bearer ${jwt.sign({ sub: 1, exp: Math.floor(Date.now() / 1000) - 5 })}` })
    await http.get("/me", { Authorization: "Bearer abc.def.ghi" })
    await http.close()
}
main()

