import { Body, CanActivate, ConflictException, Controller, ExecutionContext, Get, HttpCode, Injectable, Module, Post, Req, UnauthorizedException, UseGuards, ValidationPipe } from "@nestjs/common"
import { JwtModule, JwtService } from "@nestjs/jwt"
import { IsEmail, MinLength } from "class-validator"
import * as bcrypt from "bcryptjs"

class CredentialsDto {
    @IsEmail() email: string
    @MinLength(8) password: string
}

type User = { id: number; email: string; passwordHash: string }

@Injectable()
class AuthService {
    private users: User[] = []
    constructor(private readonly jwt: JwtService) {}
    async register({ email, password }: CredentialsDto) {
        if (this.users.some(u => u.email === email)) throw new ConflictException("Email band")
        const user = { id: this.users.length + 1, email, passwordHash: await bcrypt.hash(password, 10) }
        this.users.push(user)
        return { id: user.id, email }
    }
    async login({ email, password }: CredentialsDto) {
        const user = this.users.find(u => u.email === email)
        if (!user || !(await bcrypt.compare(password, user.passwordHash))) throw new UnauthorizedException("Email yoki parol noto'g'ri")
        return { access_token: await this.jwt.signAsync({ sub: user.id, email }) }
    }
}

@Injectable()
class JwtGuard implements CanActivate {
    constructor(private readonly jwt: JwtService) {}
    async canActivate(ctx: ExecutionContext) {
        const req = ctx.switchToHttp().getRequest()
        req.user = await this.jwt.verifyAsync(req.headers.authorization?.slice(7) ?? "").catch(() => { throw new UnauthorizedException() })
        return true
    }
}

@Controller("auth")
class AuthController {
    constructor(private readonly auth: AuthService) {}
    @Post("register") register(@Body() dto: CredentialsDto) { return this.auth.register(dto) }
    @Post("login") @HttpCode(200) login(@Body() dto: CredentialsDto) { return this.auth.login(dto) }
    @Get("me") @UseGuards(JwtGuard) me(@Req() req: any) { return { id: req.user.sub, email: req.user.email } }
}

@Module({ imports: [JwtModule.register({ secret: "s", signOptions: { expiresIn: "1h" } })], controllers: [AuthController], providers: [AuthService, JwtGuard] })
class AppModule {}

async function main() {
    const http = await testApp(AppModule, app => app.useGlobalPipes(new ValidationPipe({ whitelist: true })))
    await http.post("/auth/register", { email: "ali@mail.uz", password: "12345678" })
    await http.post("/auth/register", { email: "notogri", password: "123" })
    const res = await fetch((await http.app.getUrl()) + "/auth/login", {
        method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ email: "ali@mail.uz", password: "12345678" }),
    })
    const { access_token } = await res.json()
    console.log("POST /auth/login →", res.status, "token:", access_token.split(".").length === 3 ? "JWT ✔" : "?")
    await http.get("/auth/me")
    await http.get("/auth/me", { authorization: `Bearer ${access_token}` })
    await http.close()
}
