import { Controller, HttpCode, Module, Post, Req, Res, UnauthorizedException } from "@nestjs/common"
import { JwtModule, JwtService } from "@nestjs/jwt"
import cookieParser from "cookie-parser"

@Controller("auth")
class AuthController {
    constructor(private readonly jwt: JwtService) {}

    @Post("login") @HttpCode(200)
    async login(@Res({ passthrough: true }) res: any) {
        const refresh = await this.jwt.signAsync({ sub: 1 }, { secret: "R", expiresIn: "7d" })
        res.cookie("refresh_token", refresh, { httpOnly: true, sameSite: "strict", path: "/auth/refresh" })
        return { access_token: "..." }
    }

    @Post("refresh") @HttpCode(200)
    async refresh(@Req() req: any) {
        const p = await this.jwt.verifyAsync(req.cookies.refresh_token ?? "", { secret: "R" }).catch(() => null)
        if (!p) throw new UnauthorizedException("Refresh cookie yo'q yoki yaroqsiz")
        return { access_token: "yangi", sub: p.sub }
    }
}

@Module({ imports: [JwtModule.register({})], controllers: [AuthController] })
class AppModule {}

async function main() {
    const http = await testApp(AppModule, app => app.use(cookieParser()))
    const login = await http.post("/auth/login")
    const setCookie = login.headers.get("set-cookie")!
    console.log("cookie bayroqlari:", setCookie.split("; ").slice(1).join("; "))
    await http.post("/auth/refresh")
    await http.post("/auth/refresh", undefined, { cookie: setCookie.split(";")[0] })
    await http.close()
}
