import { BadRequestException, Controller, Get, Injectable, Module, Query } from "@nestjs/common"
import { JwtModule, JwtService } from "@nestjs/jwt"

@Injectable()
class VerifyService {
    verified = new Set<number>()
    constructor(private readonly jwt: JwtService) {}
    makeLink(userId: number) { return this.jwt.signAsync({ sub: userId, purpose: "verify-email" }, { expiresIn: "1d" }) }
    async verify(token: string) {
        const p = await this.jwt.verifyAsync(token).catch(() => null)
        if (!p || p.purpose !== "verify-email") throw new BadRequestException("Tasdiqlash havolasi yaroqsiz")
        this.verified.add(p.sub)
        return { verified: true, userId: p.sub }
    }
}

