import { CanActivate, Controller, ExecutionContext, Get, Injectable, Module, Post, Req, UnauthorizedException, UseGuards } from "@nestjs/common"
import { JwtModule, JwtService } from "@nestjs/jwt"

@Injectable() class Users { tokenVersion = new Map([[1, 0]]) }

@Injectable() class JwtGuard implements CanActivate {
    constructor(private readonly jwt: JwtService, private readonly users: Users) {}
    async canActivate(ctx: ExecutionContext) {
        const req = ctx.switchToHttp().getRequest()
        const p = await this.jwt.verifyAsync(req.headers.authorization?.slice(7) ?? "").catch(() => null)
        if (!p || p.ver !== this.users.tokenVersion.get(p.sub)) throw new UnauthorizedException("Sessiya tugagan")
        req.user = p
        return true
    }
}

