import { Body, CanActivate, Controller, ExecutionContext, Get, HttpCode, Injectable, Module, Post, Req, UnauthorizedException, UseGuards } from "@nestjs/common"
import { JwtModule, JwtService } from "@nestjs/jwt"
import { Test } from "@nestjs/testing"
import assert from "node:assert/strict"

@Injectable() class JwtGuard implements CanActivate {
    constructor(private readonly jwt: JwtService) {}
    async canActivate(ctx: ExecutionContext) {
        const req = ctx.switchToHttp().getRequest()
        req.user = await this.jwt.verifyAsync(req.headers.authorization?.slice(7) ?? "").catch(() => { throw new UnauthorizedException() })
        return true
    }
}

@Controller("auth")
class AuthController {
    constructor(private readonly jwt: JwtService) {}
    @Post("login") @HttpCode(200) async login(@Body() b: { email: string; password: string }) {
        if (b.password !== "123") throw new UnauthorizedException()
        return { accessToken: await this.jwt.signAsync({ sub: b.email }) }
    }
    @Get("me") @UseGuards(JwtGuard) me(@Req() req: any) { return { email: req.user.sub } }
}
@Module({ imports: [JwtModule.register({ secret: "test" })], controllers: [AuthController], providers: [JwtGuard] }) class AppModule {}

