const base32 = (buf: Buffer) => {
    const A = "ABCDEFGHIJKLMNOPQRSTUVWXYZ234567"
    let bits = "", out = ""
    for (const b of buf) bits += b.toString(2).padStart(8, "0")
    for (let i = 0; i < bits.length; i += 5) out += A[parseInt(bits.slice(i, i + 5).padEnd(5, "0"), 2)]
    return out
}
