import { Body, Controller, HttpCode, Module, Post, UnauthorizedException } from "@nestjs/common"
import { createHmac } from "node:crypto"

const SECRET = Buffer.from("12345678901234567890")
const NOW = 1111111109
function totp(t: number) {
    const c = Buffer.alloc(8); c.writeBigUInt64BE(BigInt(Math.floor(t / 30)))
    const h = createHmac("sha1", SECRET).update(c).digest(), o = h[h.length - 1] & 0xf
    return String((h.readUInt32BE(o) & 0x7fffffff) % 1e6).padStart(6, "0")
}
@Controller("auth/2fa") class T {
    @Post("verify") @HttpCode(200) verify(@Body("code") code: string) {
        const ok = [-30, 0, 30].some(d => totp(NOW + d) === code)
        if (!ok) throw new UnauthorizedException("Kod noto'g'ri")
        return { ok: true }
    }
}
@Module({ controllers: [T] }) class AppModule {}

async function main() {
    const http = await testApp(AppModule)
    await http.post("/auth/2fa/verify", { code: totp(NOW) })
    await http.post("/auth/2fa/verify", { code: totp(NOW - 30) })
    await http.post("/auth/2fa/verify", { code: "000000" })
    await http.close()
}
main()

