import { Body, Controller, HttpCode, Module, Post, UnauthorizedException } from "@nestjs/common"

const codes = new Map<string, { code: string; tries: number }>()
@Controller("auth/otp") class O {
    @Post("send") @HttpCode(200) send(@Body("phone") phone: string) { codes.set(phone, { code: "4821", tries: 0 }); return { sent: true, expiresIn: 120 } }
    @Post("verify") @HttpCode(200) verify(@Body() b: { phone: string; code: string }) {
        const e = codes.get(b.phone)
        if (!e) throw new UnauthorizedException("Avval kod so'rang")
        if (++e.tries > 3) { codes.delete(b.phone); throw new UnauthorizedException("Urinishlar tugadi, yangi kod so'rang") }
        if (e.code !== b.code) throw new UnauthorizedException(`Kod noto'g'ri (${e.tries}/3)`)
        codes.delete(b.phone)
        return { accessToken: "...", phone: b.phone }
    }
}
