import { Body, Controller, HttpCode, Module, Post } from "@nestjs/common"

const sleep = (ms: number) => new Promise(r => setTimeout(r, ms))
async function atLeast<T>(ms: number, work: () => Promise<T>) { const start = Date.now(); const r = await work(); const left = ms - (Date.now() - start); if (left > 0) await sleep(left); return r }
@Controller("auth") class A {
    @Post("login") @HttpCode(200) login(@Body("email") email: string) {
        return atLeast(100, async () => { if (email === "ali@mail.uz") await sleep(30); return { ok: false } })
    }
}
