        const key = req.ip
        const now = Date.now()
        const recent = (this.hits.get(key) ?? []).filter(t => now - t < this.windowMs)
        if (recent.length >= this.limit) throw new HttpException("Sekinroq! Keyinroq urinib ko'ring", 429)
        recent.push(now)
        this.hits.set(key, recent)
        return true
    }
}

