class TokenBucket {
    private tokens: number
    private last = 0
    constructor(private capacity: number, private refillPerSec: number) { this.tokens = capacity }
    take(now: number) {
        this.tokens = Math.min(this.capacity, this.tokens + ((now - this.last) / 1000) * this.refillPerSec)
        this.last = now
        if (this.tokens < 1) return false
        this.tokens--
        return true
    }
}
const b = new TokenBucket(3, 1)
const log = [0, 100, 200, 300, 1300, 1400, 3500].map(t => `${t}ms:${b.take(t) ? "✔" : "✘"}`)
console.log(log.join("  "))

const WINDOW = 10_000, LIMIT = 3
const hits: number[] = []
function allow(now: number) {
    while (hits.length && hits[0] <= now - WINDOW) hits.shift()
    if (hits.length >= LIMIT) return false
    hits.push(now)
    return true
}
for (const t of [0, 2000, 4000, 6000, 10_500, 12_500]) console.log(`${String(t / 1000).padStart(4)} s → ${allow(t) ? "ruxsat" : "429"} (oynada: ${hits.length})`)

const LIMIT = 3, WINDOW = 10_000
const times = [8000, 9000, 9500, 10_100, 10_500, 11_000]
const fixed = new Map<number, number>()
const fixedRes = times.map(t => { const w = Math.floor(t / WINDOW); const n = (fixed.get(w) ?? 0) + 1; fixed.set(w, n); return n <= LIMIT })
const log: number[] = []
const slidingRes = times.map(t => { while (log.length && log[0] <= t - WINDOW) log.shift(); if (log.length >= LIMIT) return false; log.push(t); return true })
console.log("vaqt (s):", times.map(t => t / 1000).join(", "))
console.log("fixed   :", fixedRes.map(x => (x ? "✔" : "✘")).join("    "), "→ 2 s ichida 6 ta o'tdi")
console.log("sliding :", slidingRes.map(x => (x ? "✔" : "✘")).join("    "))

const CAPACITY = 3, LEAK_MS = 1000
let level = 0, lastLeak = 0
function arrive(now: number) {
    level = Math.max(0, level - Math.floor((now - lastLeak) / LEAK_MS))
    lastLeak = now - ((now - lastLeak) % LEAK_MS)
    if (level >= CAPACITY) return "tashlandi"
    level++
    return `navbatga (${level}/${CAPACITY})`
}
for (const t of [0, 10, 20, 30, 1200, 1300, 3500]) console.log(`${t}ms → ${arrive(t)}`)

import { CanActivate, Controller, ExecutionContext, Get, HttpException, Injectable, Module, SetMetadata, UseGuards } from "@nestjs/common"
import { Reflector } from "@nestjs/core"

const budget = new Map<string, number>()
const Cost = (n: number) => SetMetadata("cost", n)
@Injectable() class CostGuard implements CanActivate {
    constructor(private r: Reflector) {}
    canActivate(ctx: ExecutionContext) {
        const key = ctx.switchToHttp().getRequest().headers["x-api-key"]
        const cost = this.r.get<number>("cost", ctx.getHandler()) ?? 1
        const left = (budget.get(key) ?? 10) - cost
        if (left < 0) throw new HttpException(`Byudjet yetmaydi: kerak ${cost}, qolgan ${budget.get(key) ?? 10}`, 429)
        budget.set(key, left)
        ctx.switchToHttp().getResponse().setHeader("X-Budget-Left", String(left))
        return true
    }
}
@Controller() @UseGuards(CostGuard) class C {
    @Get("list") @Cost(1) list() { return [] }
    @Get("report") @Cost(6) report() { return { pdf: true } }
}
@Module({ controllers: [C] }) class AppModule {}

