import { CallHandler, Controller, ExecutionContext, Get, HttpException, Injectable, Module, NestInterceptor, UseInterceptors } from "@nestjs/common"
import { finalize } from "rxjs"

const active = new Map<string, number>()
@Injectable() class ConcurrencyLimit implements NestInterceptor {
    intercept(ctx: ExecutionContext, next: CallHandler) {
        const user = ctx.switchToHttp().getRequest().headers["x-user"]
        const n = active.get(user) ?? 0
        if (n >= 2) throw new HttpException("Bir vaqtda ko'pi bilan 2 ta hisobot", 429)
        active.set(user, n + 1)
        return next.handle().pipe(finalize(() => active.set(user, (active.get(user) ?? 1) - 1)))
    }
}
@Controller("reports") @UseInterceptors(ConcurrencyLimit) class R { @Get() async r() { await new Promise(res => setTimeout(res, 50)); return "tayyor" } }
@Module({ controllers: [R] }) class AppModule {}

async function main() {
    const http = await testApp(AppModule)
    const base = await http.app.getUrl()
    const statuses = await Promise.all([1, 2, 3].map(async () => (await fetch(base + "/reports", { headers: { "x-user": "ali" } })).status))
    console.log("3 ta parallel so'rov statuslari (tartiblangan):", statuses.sort())
    await http.close()
}
main()

import { Controller, Get, Module } from "@nestjs/common"
import helmet from "helmet"

@Controller() class C { @Get() home() { return "ok" } }
@Module({ controllers: [C] }) class AppModule {}
const EXPECTED = ["content-security-policy", "strict-transport-security", "x-content-type-options", "x-frame-options", "referrer-policy", "cross-origin-opener-policy", "x-powered-by"]

async function main() {
    for (const withHelmet of [false, true]) {
        const http = await testApp(AppModule, app => { if (withHelmet) app.use(helmet()) })
        const h = (await http.get("/")).headers
        console.log(withHelmet ? "helmet bilan:" : "helmet'siz:", EXPECTED.map(k => (k === "x-powered-by" ? `${h.has(k) ? "✘" : "✔"} x-powered-by yashirilgan` : `${h.has(k) ? "✔" : "✘"} ${k}`)).join(", "))
        await http.close()
    }
}
main()

import { Controller, Get, Module } from "@nestjs/common"
import { APP_GUARD } from "@nestjs/core"
import { seconds, Throttle, ThrottlerGuard, ThrottlerModule } from "@nestjs/throttler"

@Controller("auth") @Throttle({ default: { limit: 2, ttl: seconds(60) } }) class A {
    @Get("login") login() { return "login" }
    @Get("otp") otp() { return "otp" }
}
@Controller("catalog") class C { @Get() c() { return [] } }
@Module({ imports: [ThrottlerModule.forRoot([{ ttl: seconds(60), limit: 100 }])], controllers: [A, C], providers: [{ provide: APP_GUARD, useClass: ThrottlerGuard }] }) class AppModule {}

async function main() {
    const http = await testApp(AppModule)
    for (let i = 0; i < 3; i++) await http.get("/auth/login")
    for (let i = 0; i < 3; i++) await http.get("/catalog")
    await http.close()
}
main()

import { Controller, Get, Module } from "@nestjs/common"
import { APP_GUARD } from "@nestjs/core"
import { ConfigModule, ConfigService } from "@nestjs/config"
import { ThrottlerGuard, ThrottlerModule } from "@nestjs/throttler"

@Controller("api") class A { @Get() a() { return "ok" } }
@Module({
    imports: [
        ConfigModule.forRoot({ ignoreEnvFile: true, load: [() => ({ RATE_LIMIT: "2", RATE_TTL_MS: "60000" })] }),
        ThrottlerModule.forRootAsync({ imports: [ConfigModule], inject: [ConfigService], useFactory: (c: ConfigService) => [{ ttl: Number(c.get("RATE_TTL_MS")), limit: Number(c.get("RATE_LIMIT")) }] }),
    ],
    controllers: [A], providers: [{ provide: APP_GUARD, useClass: ThrottlerGuard }],
})
class AppModule {}

async function main() {
    const http = await testApp(AppModule)
    for (let i = 0; i < 3; i++) await http.get("/api")
    await http.close()
}
main()

